import test from 'node:test';import assert from 'node:assert/strict';import{readFileSync}from'node:fs';
import{teacherSurveyPlan,required}from'./teacher-survey-scope.mjs';import{failedChecks,requiredChecks}from'./merge-gate.mjs';
const b=JSON.parse(readFileSync(new URL('./teacher-survey-bindings.json',import.meta.url))),base='a'.repeat(40),head='b'.repeat(40),entries=Object.entries(b.application).map(([file,v])=>({file,status:v.before?'M':'A',oldMode:v.before?'100644':'000000',newMode:'100644'}));
const read=(command,ref)=>ref.endsWith(':server-version/backend')?'c'.repeat(40):ref.endsWith(':server-version/frontend')?'d'.repeat(40):b.application[ref.split(':').slice(1).join(':')]?.[ref.startsWith(base)?'before':'after'];
test('admits only the reviewed source and frozen unchanged backend',()=>{const p=teacherSurveyPlan(entries,base,head,read);assert(p);assert.deepEqual(p.required,required);assert.deepEqual(p.changed,['frontend'])});
test('unknown/deleted/mode-changing/scoring/partial diffs refuse',()=>{for(const wrong of[[...entries,{file:'server-version/backend/src/index.ts',status:'M',oldMode:'100644',newMode:'100644'}],entries.slice(1),entries.map((e,i)=>i?e:{...e,status:'D'}),entries.map((e,i)=>i?e:{...e,newMode:'100755'})])assert.equal(teacherSurveyPlan(wrong,base,head,read),null)});
test('modified reviewed source or backend refuses',()=>{assert.equal(teacherSurveyPlan(entries,base,head,()=> 'f'.repeat(40)),null);assert.equal(teacherSurveyPlan(entries,base,head,(cmd,ref)=>ref===head+':server-version/backend'?'f'.repeat(40):read(cmd,ref)),null)});
test('ready gate requires candidate and SAST; failures cannot be hidden by a green draft',()=>{const p=teacherSurveyPlan(entries,base,head,read);const scope={application_route:'teacher-survey',scenario:'teacher-survey',teacher_survey_plan:JSON.stringify(p),codeql:'true',...Object.fromEntries(['media2','media7','situational_video','situational_branching','video_core','app_shell','canonical_visual','perf_smoke','ops'].map(k=>[k,'false']))};const needs={scope:{result:'success',outputs:scope},'teacher-survey':{result:'success'},codeql:{result:'success'}};assert.deepEqual(requiredChecks(needs,false),['scope','teacher-survey','codeql']);assert.deepEqual(failedChecks(needs,false),[]);for(const value of['failure','cancelled','skipped',undefined]){needs['teacher-survey'].result=value;assert(failedChecks(needs,false).includes('teacher-survey'))}assert.deepEqual(requiredChecks(needs,true),['scope'])});
